exportedFunctions.constructHEarthTriangleMesh:
function constructHEarthTriangleMesh({
  primitiveId,
  geometryId =
    `${primitiveId ?? 'mesh'}:geometry`,
  primitiveType =
    H_EARTH_3D_GEOMETRY_SOUTH_ENUMS
      .primitiveType.TRIANGLE_MESH,
  vertices,
  indices,
  normalMode =
    H_EARTH_3D_GEOMETRY_SOUTH_ENUMS
      .normalMode.FACE_AND_VERTEX,
  expectedClosure =
    H_EARTH_3D_GEOMETRY_SOUTH_ENUMS
      .expectedClosure.UNSPECIFIED,
  transform =
    createHEarthIdentityMatrix4(),
  semanticRole = null,
  materialHint = null,
  visibilityHint = null,
  interactionHint = null,
  source = null,
  attributes = null,
  metadata = null,
  toleranceContext
} = {}) {
  const issues = [];

  if (
    !isHEarthNonEmptyString(primitiveId)
  ) {
    issues.push(
      createSouthIssue(
        'SOUTH_PRIMITIVE_ID_INVALID',
        'ERROR',
        'Triangle-mesh construction requires a nonempty primitiveId.'
      )
    );
  }

  if (
    !isTriangleBearingPrimitiveType(
      primitiveType
    )
  ) {
    issues.push(
      createSouthIssue(
        'SOUTH_TRIANGLE_BEARING_PRIMITIVE_TYPE_REQUIRED',
        'ERROR',
        'Triangle-mesh construction requires a lawful triangle-bearing primitive type.',
        {
          primitiveType
        }
      )
    );
  }

  if (
    !areFiniteVector3Array(vertices) ||
    vertices.length < 3
  ) {
    issues.push(
      createSouthIssue(
        'SOUTH_MESH_VERTICES_INVALID',
        'ERROR',
        'Triangle-mesh construction requires at least three finite vertices.'
      )
    );
  }

  if (
    !areValidTriangleIndices(
      indices,
      Array.isArray(vertices)
        ? vertices.length
        : 0
    )
  ) {
    issues.push(
      createSouthIssue(
        'SOUTH_MESH_INDICES_INVALID',
        'ERROR',
        'Triangle-mesh indices must define one or more valid indexed triangles.'
      )
    );
  }

  if (
    !enumIncludes(
      H_EARTH_3D_GEOMETRY_SOUTH_ENUMS
        .normalMode,
      normalMode
    )
  ) {
    issues.push(
      createSouthIssue(
        'SOUTH_NORMAL_MODE_INVALID',
        'ERROR',
        'Triangle-mesh normal mode is unsupported.'
      )
    );
  }

  if (
    !enumIncludes(
      H_EARTH_3D_GEOMETRY_SOUTH_ENUMS
        .expectedClosure,
      expectedClosure
    )
  ) {
    issues.push(
      createSouthIssue(
        'SOUTH_EXPECTED_CLOSURE_INVALID',
        'ERROR',
        'Triangle-mesh expectedClosure is unsupported.'
      )
    );
  }

  if (
    !isHEarthMatrix4(transform)
  ) {
    issues.push(
      createSouthIssue(
        'SOUTH_TRANSFORM_INVALID',
        'ERROR',
        'Triangle-mesh transform must be a valid Matrix4.'
      )
    );
  }

  if (
    hasHEarthBlockingIssues(issues)
  ) {
    return makeConstructionFailure({
      constructionType:
        'TRIANGLE_MESH',

      issues,

      metadata
    });
  }

  const bounds =
    createHEarthGeometryBounds(
      vertices
    );

  const resolvedToleranceContext =
    resolveToleranceContext(
      toleranceContext,
      bounds
    );

  if (
    !isHEarthGeometryToleranceContext(
      resolvedToleranceContext
    )
  ) {
    issues.push(
      createSouthIssue(
        'SOUTH_TOLERANCE_CONTEXT_INVALID',
        'ERROR',
        'Triangle-mesh construction requires a valid tolerance context.'
      )
    );
  } else if (
    !isHEarthAABB3D(
      bounds,
      resolvedToleranceContext
    )
  ) {
    issues.push(
      createSouthIssue(
        'SOUTH_MESH_BOUNDS_INVALID',
        'ERROR',
        'Triangle-mesh bounds could not be derived coherently.'
      )
    );
  }

  if (
    hasHEarthBlockingIssues(issues)
  ) {
    return makeConstructionFailure({
      constructionType:
        'TRIANGLE_MESH',

      issues,

      metadata
    });
  }

  const topologyAnalysis =
    evaluateHEarthIndexedMesh(
      vertices,
      indices,
      resolvedToleranceContext
    );

  issues.push(
    ...topologyAnalysis.issues
  );

  const openNeutralMesh =
    isOpenManifoldTopologyAnalysis(
      topologyAnalysis
    );

  const closedOutward =
    isClosedOutwardTopologyAnalysis(
      topologyAnalysis
    );

  if (
    expectedClosure ===
      H_EARTH_3D_GEOMETRY_SOUTH_ENUMS
        .expectedClosure.CLOSED_REQUIRED &&
    !closedOutward
  ) {
    issues.push(
      createSouthIssue(
        'SOUTH_CLOSED_OUTWARD_TOPOLOGY_REQUIRED',
        'ERROR',
        'This constructor requires East to report a lawful closed outward result through classification, outwardClosed, directed-conflict-free topology, and satisfied closure requirements.',
        getTopologyDiagnosticDetails(
          topologyAnalysis
        )
      )
    );
  }

  if (
    expectedClosure ===
      H_EARTH_3D_GEOMETRY_SOUTH_ENUMS
        .expectedClosure.OPEN_ALLOWED &&
    !openNeutralMesh &&
    !closedOutward
  ) {
    issues.push(
      createSouthIssue(
        'SOUTH_OPEN_ALLOWED_TOPOLOGY_INVALID',
        'ERROR',
        'An open-by-design constructor may produce an open manifold or a lawful closed outward manifold, but not invalid topology.',
        getTopologyDiagnosticDetails(
          topologyAnalysis
        )
      )
    );
  }

  if (
    expectedClosure ===
      H_EARTH_3D_GEOMETRY_SOUTH_ENUMS
        .expectedClosure.UNSPECIFIED &&
    !openNeutralMesh &&
    !closedOutward
  ) {
    issues.push(
      createSouthIssue(
        'SOUTH_GENERAL_MESH_TOPOLOGY_INVALID',
        'ERROR',
        'General neutral mesh construction may not preserve invalid topology.',
        getTopologyDiagnosticDetails(
          topologyAnalysis
        )
      )
    );
  }

  if (
    hasHEarthBlockingIssues(issues)
  ) {
    return makeConstructionFailure({
      constructionType:
        'TRIANGLE_MESH',

      issues,

      metadata: {
        ...metadata,
        expectedClosure,
        topologyAnalysis
      }
    });
  }

  const normalAttachment =
    attachMeshNormals({
      vertices,
      indices,
      normalMode,
      toleranceContext:
        resolvedToleranceContext
    });

  issues.push(
    ...normalAttachment.issues
  );

  if (
    hasHEarthBlockingIssues(issues)
  ) {
    return makeConstructionFailure({
      constructionType:
        'TRIANGLE_MESH',

      issues,

      metadata: {
        ...metadata,
        expectedClosure,
        topologyAnalysis
      }
    });
  }

  const surfaceClosure =
    openNeutralMesh
      ? H_EARTH_3D_GEOMETRY_SOUTH_ENUMS
          .surfaceClosure.OPEN
      : closedOutward
        ? H_EARTH_3D_GEOMETRY_SOUTH_ENUMS
            .surfaceClosure.CLOSED
        : H_EARTH_3D_GEOMETRY_SOUTH_ENUMS
            .surfaceClosure.UNSPECIFIED;

  const geometry =
    createHEarthNeutralGeometryRecord({
      geometryId,

      topologyMode:
        H_EARTH_3D_GEOMETRY_SOUTH_ENUMS
          .topologyMode.TRIANGLES,

      vertices,

      indices,

      normals:
        normalAttachment.normals,

      faceNormals:
        normalAttachment.faceNormals,

      bounds,

      transform,

      attributes,

      source,

      metadata: {
        ...metadata,

        expectedClosure,

        topologyAnalysis,

        surfaceClosure,

        openNeutralMeshConstructionValid:
          openNeutralMesh &&
          expectedClosure !==
            H_EARTH_3D_GEOMETRY_SOUTH_ENUMS
              .expectedClosure.CLOSED_REQUIRED,

        closedOutwardConstructionValid:
          closedOutward,

        admitted:
          false,

        admissionAuthority:
          'WEST_ONLY'
      }
    });

  if (!geometry) {
    return makeConstructionFailure({
      constructionType:
        'TRIANGLE_MESH',

      issues: [
        ...issues,

        createSouthIssue(
          'SOUTH_GEOMETRY_RECORD_CREATION_FAILED',
          'ERROR',
          'Triangle-mesh geometry record could not be created.'
        )
      ],

      metadata
    });
  }

  const primitiveRecord =
    createHEarthNeutralPrimitiveRecord({
      primitiveId,

      primitiveType,

      geometry,

      semanticRole,

      materialHint,

      visibilityHint,

      interactionHint,

      metadata: {
        ...metadata,

        expectedClosure,

        openNeutralMesh,

        closedOutward,

        constructionValid:
          true,

        admitted:
          false,

        admissionAuthority:
          'WEST_ONLY'
      },

      issues
    });

  if (!primitiveRecord) {
    return makeConstructionFailure({
      constructionType:
        'TRIANGLE_MESH',

      issues: [
        ...issues,

        createSouthIssue(
          'SOUTH_PRIMITIVE_RECORD_CREATION_FAILED',
          'ERROR',
          'Triangle-mesh primitive record could not be created.'
        )
      ],

      metadata
    });
  }

  return makeConstructionSuccess({
    constructionType:
      'TRIANGLE_MESH',

    primitiveRecord,

    geometry,

    issues,

    metadata: {
      ...metadata,

      expectedClosure,

      topologyAnalysis,

      closedOutward
    },

    openNeutralMesh
  });
}

exportedFunctions.constructHEarthHeightFieldMesh:
function constructHEarthHeightFieldMesh({
  primitiveId,
  descriptor,
  xSampleCount,
  zSampleCount,
  transform =
    createHEarthIdentityMatrix4(),
  semanticRole = null,
  materialHint = null,
  metadata = null,
  toleranceContext
} = {}) {
  const sampled =
    sampleHEarthHeightField(
      descriptor,
      xSampleCount,
      zSampleCount,
      toleranceContext
    );

  if (!sampled.valid) {
    return makeConstructionFailure({
      constructionType:
        'HEIGHT_FIELD_MESH',

      issues: [
        ...sampled.issues,

        createSouthIssue(
          'SOUTH_HEIGHT_FIELD_SAMPLE_HELD',
          'ERROR',
          'Height-field sampling did not complete lawfully.'
        )
      ],

      metadata
    });
  }

  const integrity =
    evaluateHEarthGridSampleIntegrity(
      sampled
    );

  if (
    !integrity.valid ||
    integrity.topologyConstructionHeld
  ) {
    return makeConstructionFailure({
      constructionType:
        'HEIGHT_FIELD_MESH',

      issues: [
        ...sampled.issues,
        ...integrity.issues
      ],

      metadata
    });
  }

  const vertices =
    sampled.samples.map(
      (sample) =>
        sample.value
    );

  if (
    !areFiniteVector3Array(vertices)
  ) {
    return makeConstructionFailure({
      constructionType:
        'HEIGHT_FIELD_MESH',

      issues: [
        createSouthIssue(
          'SOUTH_HEIGHT_FIELD_VERTICES_INVALID',
          'ERROR',
          'Height-field samples did not resolve to finite vertices.'
        )
      ],

      metadata
    });
  }

  const wrapRows =
    sampled.secondTopology ===
      H_EARTH_3D_GEOMETRY_EAST_ENUMS
        .domainTopology.PERIODIC;

  const wrapColumns =
    sampled.firstTopology ===
      H_EARTH_3D_GEOMETRY_EAST_ENUMS
        .domainTopology.PERIODIC;

  const indices =
    constructGridTriangleIndices({
      rowCount:
        sampled.rowCount,

      columnCount:
        sampled.columnCount,

      wrapRows,

      wrapColumns,

      heightFieldWinding:
        true
    });

  if (!indices) {
    return makeConstructionFailure({
      constructionType:
        'HEIGHT_FIELD_MESH',

      issues: [
        createSouthIssue(
          'SOUTH_HEIGHT_FIELD_INDEX_CONSTRUCTION_FAILED',
          'ERROR',
          'Height-field triangle indices could not be constructed.'
        )
      ],

      metadata
    });
  }

  return constructHEarthTriangleMesh({
    primitiveId,

    primitiveType:
      H_EARTH_3D_GEOMETRY_SOUTH_ENUMS
        .primitiveType.HEIGHT_FIELD_MESH,

    vertices,

    indices,

    expectedClosure:
      wrapRows &&
      wrapColumns
        ? H_EARTH_3D_GEOMETRY_SOUTH_ENUMS
            .expectedClosure.CLOSED_REQUIRED
        : H_EARTH_3D_GEOMETRY_SOUTH_ENUMS
            .expectedClosure.OPEN_ALLOWED,

    transform,

    semanticRole,

    materialHint,

    metadata: {
      ...metadata,

      rowCount:
        sampled.rowCount,

      columnCount:
        sampled.columnCount,

      wrapRows,

      wrapColumns,

      windingLaw:
        '[a,c,b] [a,d,c]',

      orientationLaw:
        'S_V_CROSS_S_U',

      rejectedSamplesCompacted:
        false,

      admitted:
        false,

      admissionAuthority:
        'WEST_ONLY'
    },

    source: {
      sourceType:
        'HEIGHT_FIELD_DESCRIPTOR',

      descriptorId:
        descriptor?.descriptorId ??
        null
    },

    toleranceContext
  });
}

exportedFunctions.createHEarthNeutralGeometryRecord:
function createHEarthNeutralGeometryRecord({
  geometryId,
  topologyMode,
  vertices,
  indices = [],
  normals = null,
  faceNormals = null,
  bounds,
  transform =
    createHEarthIdentityMatrix4(),
  attributes = null,
  source = null,
  metadata = null
} = {}) {
  if (
    !isHEarthNonEmptyString(geometryId) ||
    !enumIncludes(
      H_EARTH_3D_GEOMETRY_SOUTH_ENUMS
        .topologyMode,
      topologyMode
    ) ||
    !areFiniteVector3Array(vertices) ||
    !Array.isArray(indices) ||
    !isHEarthMatrix4(transform) ||
    !isHEarthAABB3D(bounds)
  ) {
    return null;
  }

  if (
    topologyMode ===
      H_EARTH_3D_GEOMETRY_SOUTH_ENUMS
        .topologyMode.TRIANGLES &&
    !areValidTriangleIndices(
      indices,
      vertices.length
    )
  ) {
    return null;
  }

  if (
    topologyMode ===
      H_EARTH_3D_GEOMETRY_SOUTH_ENUMS
        .topologyMode.LINES &&
    !areValidLineIndices(
      indices,
      vertices.length
    )
  ) {
    return null;
  }

  if (
    normals !== null &&
    (
      !areFiniteVector3Array(normals) ||
      normals.length !== vertices.length
    )
  ) {
    return null;
  }

  if (
    faceNormals !== null &&
    !Array.isArray(faceNormals)
  ) {
    return null;
  }

  const clonedVertices =
    cloneVector3Array(vertices);

  const clonedNormals =
    normals === null
      ? null
      : cloneVector3Array(normals);

  if (
    !clonedVertices ||
    (
      normals !== null &&
      !clonedNormals
    )
  ) {
    return null;
  }

  return deepFreeze({
    recordType:
      'H_EARTH_PROJECTION_NEUTRAL_GEOMETRY_RECORD',

    geometryId,

    coordinateFrame:
      H_EARTH_3D_GEOMETRY_COORDINATE_FRAME,

    projectionNeutral:
      true,

    topologyMode,

    vertices:
      deepFreeze(clonedVertices),

    indices:
      deepFreeze(indices.slice()),

    normals:
      clonedNormals === null
        ? null
        : deepFreeze(clonedNormals),

    faceNormals:
      faceNormals === null
        ? null
        : freezeClone(faceNormals),

    bounds,

    transform,

    attributes:
      freezeClone(attributes),

    source:
      freezeClone(source),

    metadata:
      freezeClone(metadata),

    admitted:
      false,

    admissionAuthority:
      'WEST_ONLY',

    providerOutput:
      false,

    rendererMaterialized:
      false
  });
}

exportedFunctions.constructHEarthGroundProvider:
function constructHEarthGroundProvider({
  providerId =
    'H_EARTH_GROUND_PROVIDER',

  providerRole =
    H_EARTH_3D_GEOMETRY_GROUND_PROVIDER_ENUMS
      .providerRole.GROUND,

  sourceZoneIds = [],
  sourceObjectIds = [],

  descriptor =
    createProviderDefaultDescriptor(),

  toleranceContext
} = {}) {
  const issues = [];

  if (!isHEarthNonEmptyString(providerId)) {
    issues.push(
      createGroundProviderIssue(
        'GROUND_PROVIDER_ID_INVALID',
        'ERROR',
        'Ground provider requires a nonempty providerId.'
      )
    );
  }

  if (
    !enumIncludes(
      H_EARTH_3D_GEOMETRY_GROUND_PROVIDER_ENUMS
        .providerRole,
      providerRole
    )
  ) {
    issues.push(
      createGroundProviderIssue(
        'GROUND_PROVIDER_ROLE_INVALID',
        'ERROR',
        'Ground provider role is unsupported.'
      )
    );
  }

  const toleranceResolution =
    resolveGroundToleranceContext(
      toleranceContext
    );

  issues.push(
    ...toleranceResolution.issues
  );

  if (
    hasHEarthBlockingIssues(
      issues
    )
  ) {
    return createHEarthGroundProviderResult({
      providerId:
        isHEarthNonEmptyString(
          providerId
        )
          ? providerId
          : 'H_EARTH_GROUND_PROVIDER',
      providerRole:
        enumIncludes(
          H_EARTH_3D_GEOMETRY_GROUND_PROVIDER_ENUMS
            .providerRole,
          providerRole
        )
          ? providerRole
          : H_EARTH_3D_GEOMETRY_GROUND_PROVIDER_ENUMS
              .providerRole.GROUND,
      sourceZoneIds,
      sourceObjectIds,
      valid:
        false,
      ineligible:
        false,
      fatal:
        true,
      primitives:
        [],
      bounds:
        getEmptyProviderBounds(),
      issues,
      receipts:
        [],
      strategy:
        null,
      requestedPrimitiveCount:
        1
    });
  }

  const strategyResolution =
    resolveGroundStrategy(
      descriptor
    );

  issues.push(
    ...strategyResolution.issues
  );

  if (
    strategyResolution.ineligible ===
    true
  ) {
    return createHEarthGroundProviderResult({
      providerId,
      providerRole,
      sourceZoneIds,
      sourceObjectIds,
      valid:
        false,
      ineligible:
        true,
      fatal:
        false,
      primitives:
        [],
      bounds:
        getEmptyProviderBounds(),
      issues,
      receipts:
        [],
      strategy:
        strategyResolution.strategy,
      requestedPrimitiveCount:
        0
    });
  }

  if (
    strategyResolution.fatal ===
    true
  ) {
    return createHEarthGroundProviderResult({
      providerId,
      providerRole,
      sourceZoneIds,
      sourceObjectIds,
      valid:
        false,
      ineligible:
        false,
      fatal:
        true,
      primitives:
        [],
      bounds:
        getEmptyProviderBounds(),
      issues,
      receipts:
        [],
      strategy:
        strategyResolution.strategy,
      requestedPrimitiveCount:
        1
    });
  }

  const primitiveConstruction =
    constructGroundPrimitiveFromStrategy({
      providerId,
      providerRole,
      sourceZoneIds,
      sourceObjectIds,
      descriptor,
      strategy:
        strategyResolution.strategy,
      toleranceContext:
        toleranceResolution
          .toleranceContext
    });

  issues.push(
    ...ensureArray(
      primitiveConstruction.issues
    )
  );

  if (
    primitiveConstruction.valid !== true ||
    !isHEarthNeutralPrimitiveRecord(
      primitiveConstruction
        .primitiveRecord
    )
  ) {
    return createHEarthGroundProviderResult({
      providerId,
      providerRole,
      sourceZoneIds,
      sourceObjectIds,
      valid:
        false,
      ineligible:
        false,
      fatal:
        true,
      primitives:
        [],
      bounds:
        getEmptyProviderBounds(),
      issues,
      receipts:
        [],
      strategy:
        strategyResolution.strategy,
      requestedPrimitiveCount:
        1
    });
  }

  const primitives = [
    primitiveConstruction
      .primitiveRecord
  ];

  const bounds =
    mergeProviderBounds(
      primitives.map(
        (primitive) =>
          primitive.geometry.bounds
      ),
      toleranceResolution
        .toleranceContext
    );

  const boundsContext =
    isHEarthAABB3D(bounds)
      ? deriveHEarthGeometryToleranceContext(
          bounds
        )
      : null;

  if (
    !isHEarthAABB3D(bounds) ||
    (
      boundsContext !== null &&
      !isHEarthGeometryToleranceContext(
        boundsContext
      )
    )
  ) {
    issues.push(
      createGroundProviderIssue(
        'GROUND_PROVIDER_MERGED_BOUNDS_INVALID',
        'ERROR',
        'Ground provider merged bounds are invalid.'
      )
    );

    return createHEarthGroundProviderResult({
      providerId,
      providerRole,
      sourceZoneIds,
      sourceObjectIds,
      valid:
        false,
      ineligible:
        false,
      fatal:
        true,
      primitives:
        [],
      bounds:
        getEmptyProviderBounds(),
      issues,
      receipts:
        [],
      strategy:
        strategyResolution.strategy,
      requestedPrimitiveCount:
        1
    });
  }

  const primitiveReceipt =
    buildGroundProviderReceipt({
      providerId,
      providerRole,
      primitiveRecord:
        primitiveConstruction
          .primitiveRecord,
      issues:
        primitiveConstruction.issues,
      sourceZoneIds,
      sourceObjectIds,
      strategy:
        strategyResolution.strategy
    });

  return createHEarthGroundProviderResult({
    providerId,
    providerRole,
    sourceZoneIds,
    sourceObjectIds,
    valid:
      !hasHEarthBlockingIssues(
        issues
      ),
    ineligible:
      false,
    fatal:
      hasHEarthBlockingIssues(
        issues
      ),
    primitives,
    bounds,
    issues,
    receipts:
      primitiveReceipt
        ? [primitiveReceipt]
        : [],
    strategy:
      strategyResolution.strategy,
    requestedPrimitiveCount:
      1
  });
}

exportedFunctions.previewHEarthWetSandGeometry:
function previewHEarthWetSandGeometry(input) {
  const inputCheck =
    checkHEarthWetSandPreviewTranslationInput(input);

  if (!inputCheck.ok) {
    return buildRejectedResult({
      sourceObjectId:
        inputCheck.normalizedInput.sourceObjectId,
      requestId:
        inputCheck.normalizedInput.requestId,
      requestedPurpose:
        inputCheck.normalizedInput.requestedPurpose,
      issues:
        inputCheck.issues
    });
  }

  const packet001Result =
    resolveHEarthSourceObjectGeometryRequest({
      sourceObjectId:
        inputCheck.normalizedInput.sourceObjectId,
      requestedPurpose:
        inputCheck.normalizedInput.requestedPurpose,
      requestId:
        inputCheck.normalizedInput.requestId
    });

  return constructHEarthWetSandPreview({
    packet001Result,
    wetSandProfile:
      H_EARTH_3D_WET_SAND_NUMERIC_CONSTRUCTION_PROFILE
  });
}

exportedFunctions.buildHEarthPostWestAdmittedGeometryTrans:
function buildHEarthPostWestAdmittedGeometryTransfer(
  input
) {
  const inputEvaluation =
    evaluateHEarthPostWestAdmittedGeometryTransferInput(
      input
    );

  if (!inputEvaluation.ok) {
    return Object.freeze({
      ok: false,
      status:
        'H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_REJECTED',
      contractId:
        H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_CONTRACT_ID,
      issues:
        inputEvaluation.issues
    });
  }

  const {
    toleranceValidation,
    previewValidation,
    westBatchValidation
  } = inputEvaluation;

  const admittedPrimitivesSnapshot =
    snapshotForTransfer(
      westBatchValidation.admittedPrimitives,
      'admittedPrimitives'
    );

  if (!admittedPrimitivesSnapshot.ok) {
    return Object.freeze({
      ok: false,
      status:
        'H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_REJECTED',
      contractId:
        H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_CONTRACT_ID,
      issues: freezeIssues([
        admittedPrimitivesSnapshot.error
      ])
    });
  }

  const frameSnapshot =
    snapshotForTransfer(
      westBatchValidation.frame,
      'aggregateFrameAdmissionRecord'
    );

  if (!frameSnapshot.ok) {
    return Object.freeze({
      ok: false,
      status:
        'H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_REJECTED',
      contractId:
        H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_CONTRACT_ID,
      issues: freezeIssues([
        frameSnapshot.error
      ])
    });
  }

  const boundsSnapshot =
    snapshotForTransfer(
      westBatchValidation.bounds,
      'bounds'
    );

  if (!boundsSnapshot.ok) {
    return Object.freeze({
      ok: false,
      status:
        'H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_REJECTED',
      contractId:
        H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_CONTRACT_ID,
      issues: freezeIssues([
        boundsSnapshot.error
      ])
    });
  }

  const toleranceSnapshot =
    toleranceValidation.normalizedValue === null
      ? {
          ok: true,
          value: null
        }
      : snapshotForTransfer(
          toleranceValidation.normalizedValue,
          'toleranceContext'
        );

  if (!toleranceSnapshot.ok) {
    return Object.freeze({
      ok: false,
