        H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_CONTRACT_ID,
      issues: freezeIssues([
        toleranceSnapshot.error
      ])
    });
  }

  return deepFreeze({
    ok: true,

    status:
      SUCCESS_STATUS,

    contractId:
      H_EARTH_POST_WEST_ADMITTED_GEOMETRY_TRANSFER_CONTRACT_ID,

