function validatePacket002Transfer(
  packet002Transfer,
  presentationMode
) {
  const issues = [];

  if (!isPlainRecord(packet002Transfer)) {
    return Object.freeze({
      ok: false,

      issues: freezeIssues([
        createBridgeIssue(
          'PACKET_002_TRANSFER_NOT_PLAIN_RECORD',
